        style: {
            layout_flexGrow: type1,
            layout_flexBasisPercent: type2
        }
    });
};

var x = [{
        u: "http://m.xxxbiquge.info/xclass/0/1.html",
        ti: "༺ˇ»`类型分类´«ˇ༻",
        reb: /(\d+)\.html/,
        rea: "{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.info/quanben.html",
        ti: "༺ˇ»`全本分类´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
