@js:
(() => {
    item = java.getElements("ul.1@li")
    od = org.jsoup.Jsoup.parse(item).select("li").eachAttr("data-id")
    x = Array.from(item)
    if (od) {
        return x.sort((a, b)=>{
         	ia = x.indexOf(a)
         	ib = x.indexOf(b)
         return od[ia]-od[ib]
        	})
    }
    return x
})();

